INSERT INTO `mod_spec_templates` (`tpl_id`, `app_cod`, `tpl_name`, `tpl_level`, `tpl_help`, `tpl_spec`, `tpl_sort`, `is_active`, `updated_at`) VALUES
(1, 'CUS', 'Custom', 'base', 'Nessuno schema fisso: \'Custom\' è la scelta per un mod_spec libero, quando nessun altro template si applica o stai prototipando un formato nuovo (es. per uno script JSX/PJS che legge le proprie chiavi da spec.params, o per un modulo che non ha ancora un template dedicato qui sotto).\n\nL\'unico vincolo è che il testo nell\'editor sia JSON valido — nessun campo è letto automaticamente da questo template. Se il modulo di destinazione (obj_app) ha un proprio schema mod_spec, scegli invece il template dedicato a quel modulo qui nell\'elenco: descrive i campi realmente letti dal renderer.', '{\"type\": \"custom\"}', 10, 1, '2026-09-28 21:49:53'),
(2, 'JSX', 'JSX — Base', 'base', 'Grafico JSXGraph generico — punto di partenza neutro (bounding box quadrato ±6, assi visibili, senza griglia).\n\nIl DISEGNO non sta nel modello: si scrive in un nodo \'JSX/Script\' di un flow collegato all\'oggetto. Il nodo riceve board (la tavola già creata con queste opzioni), JXG (la libreria) e params (da questa spec). Contiene codice: finché il flow non è validato gira solo per il suo autore. Dal 2026-09-28 il vecchio file .mjs del modello non viene più eseguito: per riusarlo copiare il corpo della sua funzione setup(board, JXG, params) nel nodo. Il modello può quindi essere \"Nessun file (dati dal flow)\". Più modelli = più tavole, scelte dal menu sinistro.\n\nCampi:\n- boundingbox [xMin, yMax, xMax, yMin]: estensione iniziale del piano visibile. Attenzione all\'ordine: NON è [xMin,xMax,yMin,yMax] ma angolo alto-sinistra e poi basso-destra (convenzione di JSXGraph).\n- axis (bool): assi cartesiani con tacche numerate.\n- grid (bool): griglia di sfondo.\n- keepaspectratio (bool): scala 1:1 fra X e Y (un cerchio resta un cerchio anche ridimensionando il pannello).\n- showNavigation (bool): pulsantini di zoom/spostamento in basso a destra.\n- boardOptions (object): qualsiasi opzione nativa della board JSXGraph, passata a JXG.JSXGraph.initBoard() (es. { pan: { enabled: false }, zoom: { enabled: false } } per bloccare la vista).\n- params (object): valori liberi passati al nodo JSX/Script come params — così lo STESSO flow disegna figure diverse in modelli diversi (es. {tipo:\'ellisse\',a:3,b:2} e {tipo:\'iperbole\',a:2,b:3}). Il contenuto dipende da cosa si aspetta il codice: non è validato qui.', '{\"axis\": true, \"grid\": false, \"params\": {}, \"boundingbox\": [-6.0, 6.0, 6.0, -6.0], \"boardOptions\": {}, \"showNavigation\": true, \"keepaspectratio\": false}', 10, 1, '2026-10-13 10:16:31'),
(3, 'JSX', 'JSX — Quadrato 1:1', 'base', 'Variante con keepaspectratio=true e showNavigation=false — per costruzioni geometriche dove le proporzioni contano (cerchi, triangoli) e la vista non deve essere spostata; griglia attiva per leggere le coordinate.\n\nStessi campi del template \'JSX — Base\' (boundingbox, axis, grid, keepaspectratio, showNavigation, boardOptions, params): vedi quella voce. Anche qui il disegno sta in un nodo \'JSX/Script\' di un flow collegato all\'oggetto, non in un file del modello.', '{\"axis\": true, \"grid\": true, \"params\": {}, \"boundingbox\": [-5.0, 5.0, 5.0, -5.0], \"boardOptions\": {}, \"showNavigation\": false, \"keepaspectratio\": true}', 20, 1, '2026-10-13 10:16:31'),
(4, 'JSX', 'JSX — Ampio senza assi', 'base', 'Bounding box più ampio (±10) e assi nascosti — per disegni liberi o diagrammi dove gli assi cartesiani distrarrebbero (una costruzione geometrica pura).\n\nStessi campi del template \'JSX — Base\': vedi quella voce. Il disegno sta in un nodo \'JSX/Script\' di un flow collegato all\'oggetto.', '{\"axis\": false, \"grid\": false, \"params\": {}, \"boundingbox\": [-10.0, 10.0, 10.0, -10.0], \"boardOptions\": {}, \"showNavigation\": true, \"keepaspectratio\": false}', 30, 1, '2026-10-13 10:16:31'),
(5, 'JSX', 'JSX — Paraboloide iperbolico 3D', 'advanced', 'Esempio con boardOptions che bloccano spostamento e zoom (vista fissa, coerente con una scena 3D disegnata in 2D) e con params ricchi — mostra come il codice del disegno possa leggere una configurazione strutturata invece di soli numeri.\n\nFunziona solo insieme al flow che disegna il paraboloide (nodo \'JSX/Script\' collegato all\'oggetto): il file .mjs di un tempo non viene più eseguito.\n\nCampi comuni (boundingbox, axis, grid, showNavigation): vedi \'JSX — Base\'. keepaspectratio è assente: se omesso vale false.\n\nboardOptions: { pan:{enabled:false}, zoom:{enabled:false} }.\n\nparams (specifici del codice del paraboloide — con un altro disegno vanno adattati):\n- box [min,max]: dominio X/Y del paraboloide.\n- boxZ [min,max]: estensione dell\'asse Z.\n- colorSup / colorTan / colorSezX / colorSezY: colori di superficie, piano tangente e sezioni.\n- tangentExt: quanto il piano tangente sporge oltre il punto di tangenza.', '{\"axis\": false, \"grid\": false, \"params\": {\"box\": [-2.5, 2.5], \"boxZ\": [-7.0, 7.0], \"colorSup\": \"#3070d0\", \"colorTan\": \"#e05820\", \"colorSezX\": \"#22c060\", \"colorSezY\": \"#d0b800\", \"tangentExt\": 1.4}, \"boundingbox\": [-5.0, 5.0, 5.0, -5.0], \"boardOptions\": {\"pan\": {\"enabled\": false}, \"zoom\": {\"enabled\": false}}, \"showNavigation\": false}', 40, 1, '2026-10-13 10:16:31'),
(6, 'MPS', 'Google Maps 3D', 'base', 'Vista 3D (fotorealistica, Photorealistic 3D Tiles di Google Maps) con eventuali marker geolocalizzati.\n\nCampi:\n- type: \"3D\" — seleziona la modalità 3D del modulo (l\'altra è \"2D\", vedi template gemello \'Google Maps 2D\'). Default del modulo se omesso: \"3D\".\n- geoCoord [lat, lng]: punto su cui la camera è centrata all\'apertura.\n- altitude (numero, metri): quota della camera sopra il livello del suolo. Usato solo in modalità 3D (ignorato in 2D).\n- tilt (numero, gradi): inclinazione della camera rispetto alla verticale (0 = vista dall\'alto, 90 = vista all\'orizzonte). Usato solo in modalità 3D.\n- coordinates (array di marker): ogni elemento è { lat, lng, altitude?, nome?, id_mrk?, colore? }.\n  - lat/lng: posizione del marker (obbligatori).\n  - altitude: quota del marker sopra il suolo (opzionale, default 0).\n  - nome: etichetta mostrata sul marker (opzionale).\n  - id_mrk: identificatore libero che correla il marker cliccato a un dato esterno — viene incluso nel payload dell\'evento App Bus \'selection:change\' e in marker.dataset.mpsIdMrk, utile per collegare il click a un record di un\'altra app (opzionale ma consigliato se usi l\'integrazione bus).\n  - colore: colore hex (es. \"#FBBC04\") dello sfondo del pin; se assente usa il pin verde default di Google (opzionale).\n\nNota: i marker (coordinates) sono disegnati solo in modalità 3D — in 2D il modulo mostra solo il centro/zoom, senza marker.', '{\"tilt\": 60, \"type\": \"3D\", \"altitude\": 150, \"geoCoord\": [45.434158, 12.338474], \"coordinates\": [{\"lat\": 45.434158, \"lng\": 12.338474, \"nome\": \"Nome luogo\", \"colore\": \"#FBBC04\", \"id_mrk\": \"m1\", \"altitude\": 0}]}', 10, 1, '2026-09-28 21:49:53'),
(7, 'MPS', 'Google Maps 2D', 'base', 'Vista 2D (mappa piatta stile Google Maps classico), senza modello 3D degli edifici.\n\nCampi:\n- type: \"2D\" — seleziona la modalità 2D del modulo (default del modulo se omesso è \"3D\", quindi qui va sempre indicato esplicitamente).\n- geoCoord [lat, lng]: punto su cui la mappa è centrata all\'apertura.\n- zoom (numero): livello di zoom iniziale di Google Maps (valori tipici 0=mondo intero, 20=singolo edificio). Usato solo in modalità 2D (ignorato in 3D, che usa altitude/tilt invece — vedi template \'Google Maps 3D\').\n- coordinates: stesso formato del template 3D, MA in modalità 2D non viene disegnato alcun marker (il campo è accettato per compatibilità di schema ma senza effetto visivo) — lascialo vuoto [] se stai usando la 2D.', '{\"type\": \"2D\", \"zoom\": 8, \"geoCoord\": [45.434158, 12.338474], \"coordinates\": []}', 20, 1, '2026-09-28 21:49:53'),
(8, 'TJS', 'GLTF', 'base', 'Modello 3D in formato glTF/GLB (con eventuale compressione Draco integrata nel file).\n\n- type: \"gltf\" — SOLO INFORMATIVO: il caricatore viene scelto in automatico in base all\'estensione del file caricato in mod_abs_url (.gltf o .glb), non da questo campo. Cambiarlo non cambia il comportamento.\n- transform.position [x,y,z]: posizione del modello nella scena, in unità scena (default [0,0,0] se l\'intero blocco transform è assente).\n- transform.rotation [rx,ry,rz]: rotazione Euler XYZ, IN RADIANTI (non gradi) — es. per 90° usa Math.PI/2 ≈ 1.5708.\n- transform.scale [sx,sy,sz]: fattore di scala per asse (default [1,1,1]).\n\nSe l\'intero blocco \'transform\' è assente, il modello resta nella trasformazione originale del file (nessuna modifica applicata).', '{\"type\": \"gltf\", \"transform\": {\"scale\": [1.0, 1.0, 1.0], \"position\": [0.0, 0.0, 0.0], \"rotation\": [0.0, 0.0, 0.0]}}', 10, 1, '2026-09-28 21:49:53'),
(9, 'TJS', 'OBJ', 'base', 'Modello 3D in formato Wavefront OBJ (con eventuale file .mtl di materiali associato automaticamente, stesso nome file, stessa cartella).\n\n- type: \"obj\" — SOLO INFORMATIVO, vedi nota sul caricamento automatico per estensione nel template \'GLTF\' qui sopra.\n- transform.position / rotation (radianti) / scale: identici al template \'GLTF\' — vedi quella voce per i dettagli.', '{\"type\": \"obj\", \"transform\": {\"scale\": [1.0, 1.0, 1.0], \"position\": [0.0, 0.0, 0.0], \"rotation\": [0.0, 0.0, 0.0]}}', 20, 1, '2026-09-28 21:49:53'),
(10, 'TJS', 'DRC', 'base', 'Nuvola di punti in formato Draco compresso (.drc) — caricata come THREE.Points (vertex color, nessuna mesh/superficie).\n\n- type: \"drc\" — SOLO INFORMATIVO, vedi nota sul caricamento automatico per estensione nel template \'GLTF\' qui sopra.\n- transform.position / rotation (radianti) / scale: identici al template \'GLTF\' — vedi quella voce per i dettagli.', '{\"type\": \"drc\", \"transform\": {\"scale\": [1.0, 1.0, 1.0], \"position\": [0.0, 0.0, 0.0], \"rotation\": [0.0, 0.0, 0.0]}}', 30, 1, '2026-09-28 21:49:53'),
(11, 'TJS', 'Pano360', 'base', 'Panorama sferico 360° a partire da una singola immagine equirettangolare (.png/.jpg/.jpeg) proiettata sull\'interno di una sfera — la camera parte al centro della sfera.\n\n- type: \"pano360\" — SOLO INFORMATIVO: il caricamento come panorama sferico scatta in automatico per QUALSIASI file .png/.jpg/.jpeg caricato in mod_abs_url per questo modulo, non per via di questo campo.\n- raggio (numero): raggio della sfera geometrica su cui è proiettata la texture, in unità scena. Default 10 se il campo è assente. Valori più grandi allontanano visivamente i dettagli dell\'immagine (la sfera stessa resta invisibile: sei sempre al centro).\n- meridiani (intero): segmenti orizzontali della sfera (longitudine) — più alto = mesh più fine ma più pesante. Default 60 se assente.\n- paralleli (intero): segmenti verticali della sfera (latitudine). Default 40 se assente.\n- transform.position / rotation (radianti) / scale: stesso blocco degli altri template TJS (vedi \'GLTF\') — qui utile soprattutto per orientare la sfera (rotation) se il nord dell\'equirettangolare non corrisponde alla vista iniziale desiderata.', '{\"type\": \"pano360\", \"raggio\": 10, \"meridiani\": 60, \"paralleli\": 40, \"transform\": {\"scale\": [1.0, 1.0, 1.0], \"position\": [0.0, 0.0, 0.0], \"rotation\": [0.0, 0.0, 0.0]}}', 40, 1, '2026-09-28 21:49:53'),
(13, 'OWL', 'OWL', 'base', 'Grafo di un\'ontologia (classi/individui/proprietà) letta da un file .ttl/.owl/.rdf/.nt/.n3/.trig e disegnata con Cytoscape.js. Tutti i campi sono opzionali.\n\n- format: formato di serializzazione RDF del file. Valori ammessi: \"turtle\", \"rdf-xml\", \"n-triples\", \"n3\", \"trig\". Se omesso, viene auto-rilevato dall\'estensione di mod_abs_url (.ttl→turtle, .owl/.rdf→rdf-xml, .nt→n-triples, .n3→n3, .trig→trig; estensione sconosciuta→turtle di default). Impostalo esplicitamente solo se l\'estensione del file non riflette il formato reale.\n- layout: algoritmo di disposizione del grafo. Valori ammessi: \"dagre\" (gerarchico rank-based, ideale per tassonomie con subClassOf profondi — default), \"cose\" (force-directed, per grafi densi con molte proprietà), \"circle\" (circolare, per ontologie piccole/panoramica rapida), \"breadthfirst\" (per livelli, gerarchia piatta). Cambiabile anche a runtime dal dropdown nella toolbar del pannello.\n- filter.showClasses / showIndividuals / showProperties (booleani): quali categorie di nodi includere nel grafo — utile per ontologie molto grandi dove vuoi vedere solo la tassonomia (showIndividuals:false) o solo i dati (showClasses:false).', '{\"filter\": {\"showClasses\": true, \"showProperties\": true, \"showIndividuals\": true}, \"format\": \"rdf-xml\", \"layout\": \"dagre\"}', 10, 1, '2026-09-28 21:49:53'),
(14, 'PDF', 'PDF', 'base', 'Documento PDF con annotazioni e viste salvate. Il file viene sempre dal campo File del modello (mod_abs_url), non dalla spec. Più PDF collegati allo stesso oggetto compaiono nel menu sinistro, ognuno con la sua spec.\n\nCampi (letti a ogni apertura del documento):\n- rotation (0 | 90 | 180 | 270): rotazione iniziale delle pagine, per i documenti scansionati storti. Ogni altro valore vale 0.\n- spread (bool): apre a doppia pagina affiancata. Default false.\n- textLayer (bool): testo selezionabile, necessario per evidenziare brani. Default false; si attiva anche dalla barra del pannello.\n\nAll\'apertura il documento si adatta da solo: alla larghezza per pagine verticali, alla pagina intera per quelle orizzontali.\n\nEvidenziazioni e viste salvate NON stanno nella spec: sono nella tabella pdf_highlights, legate al modello, e si creano dal pannello (selezione del testo, \"Salva vista\"). Le modifica chi le ha scritte, il responsabile scientifico o l\'amministratore.', '{\"spread\": false, \"rotation\": 0, \"textLayer\": true}', 10, 1, '2026-10-13 10:16:31'),
(15, 'DBJ', 'JSON Tabulator', 'base', 'Tabella con dati JSON incorporati DIRETTAMENTE nel mod_spec (non c\'è un database esterno: i record vivono qui). mod_spec è OBBLIGATORIO per questo modulo — se assente, il pannello mostra un errore ed esce.\n\nCampi:\n- data.records (array di oggetti, obbligatorio): i dati veri e propri, una riga per oggetto. Le chiavi dei singoli oggetti diventano le colonne se \'view.columns\' è assente (auto-rilevate dal primo record).\n- view.columns (array, opzionale): definisce esplicitamente le colonne da mostrare, in ordine. Ogni voce: { field, caption?, width?, mode? }.\n  - field: nome della chiave in data.records da mostrare in questa colonna (obbligatorio).\n  - caption: intestazione mostrata (opzionale, default = field).\n  - width: larghezza colonna in pixel (opzionale).\n  - mode: \"r\" (sola lettura) o \"rw\" (cella cliccabile/editabile — default \"rw\" se omesso). ATTENZIONE: \'rw\' rende la cella editabile SOLO nell\'interfaccia — non esiste alcun salvataggio automatico della modifica da nessuna parte nel codice attuale: il valore digitato si perde al refresh/riapertura del pannello. Usa \'rw\' solo per uso temporaneo/dimostrativo, non per raccogliere dati persistenti.\n- busKey (stringa, opzionale): nome del campo (deve esistere in ogni record) usato per emettere l\'evento App Bus \'selection:change\' al click su una riga — payload { objId, sourceApp:\'DBJ\', field: busKey, value, row }. Se assente, il click su una riga non emette nulla sul bus (ma è comunque disponibile localmente per un flow FLE embedded tramite il nodo \'Events/OnRowSelected\', che scatta sempre indipendentemente da busKey).\n\nQuesta tabella si aggiorna anche ricevendo l\'evento bus \'data:refresh\': ricarica l\'intero mod_spec dal server (utile se un flow FLE o un altro pannello ha modificato mod_spec.data.records lato server) — non è un filtro, ricarica tutto.', '{\"data\": {\"records\": [{\"campo1\": \"valore\", \"campo2\": 42}]}, \"view\": {\"columns\": [{\"mode\": \"r\", \"field\": \"campo1\", \"width\": 200, \"caption\": \"Campo 1\"}, {\"mode\": \"rw\", \"field\": \"campo2\", \"caption\": \"Campo 2\"}]}, \"busKey\": \"campo1\"}', 10, 1, '2026-09-28 21:49:53'),
(16, 'MYS', 'MySQL Tabulator', 'base', 'Tabella collegata a una VERA tabella MySQL del database applicativo, via api/grid.php — l\'unico dei tre visualizzatori tabellari (insieme a DBJ e CSV) con scrittura realmente persistita, e l\'unico con filtro/ricerca reali.\n\nCampi:\n- table (stringa, OBBLIGATORIO): nome della tabella MySQL da interrogare.\n- apiUrl (stringa, opzionale, default \"api/grid.php\"): endpoint usato per lettura/scrittura — cambialo solo se hai un endpoint dedicato compatibile.\n- fields (array, opzionale, default [\"*\"]): colonne SQL da selezionare (SELECT).\n- where (array, opzionale, default []): condizioni iniziali sempre applicate, es. [{ field:\"x\", op:\"=\", value:\"y\" }] — combinabili, si sommano ai filtri applicati a runtime (ricerca, evento bus \'filter:apply\', nodo flow Data/Refresh).\n- orderBy (array, opzionale): ordinamento iniziale, es. [{ field:\"data\", dir:\"desc\" }].\n- limit (numero, opzionale, default 200): massimo numero di righe caricate per richiesta.\n- pageSize (numero, opzionale, default 25): righe per pagina nella griglia.\n- pkField (stringa, opzionale): campo chiave primaria — se assente viene usato quello indicato dal server nella risposta. Necessario per far funzionare update/delete riga.\n- searchFields (array, opzionale, default: tutte le colonne): campi su cui agisce la casella di ricerca full-text client-side nella toolbar interna del pannello.\n- columns (array, opzionale, default: auto-rilevate dal primo record): definizione colonne, ogni voce { field, title?, width?, frozen?, formatter?, colors? }.\n  - formatter (stringa): \"date\" (localizzata it-IT), \"datetime\" (idem con ora), \"money\" (2 decimali, it-IT), \"boolean\" (✔/✗), \"badge\" (etichetta colorata — richiede colors: { valore: \"#hex\", ... } per mappare ogni valore possibile a un colore).\n- busKey (stringa, opzionale): campo usato per l\'evento App Bus \'selection:change\' al click riga (payload { objId, sourceApp:\'MYS\', field, value, row }) — se assente disabilita solo l\'emissione bus, non il click in sé.\n\nScrittura: attiva SOLO se il server risponde writable:true per questa tabella (permesso lato backend, non configurabile da qui) — in tal caso compaiono in automatico la colonna azioni (✓/✗/🗑) e l\'editing inline a doppio click. Se writable è false, la tabella è di sola lettura anche con mode \'rw\' su una colonna.', '{\"limit\": 200, \"table\": \"nome_tabella\", \"where\": [{\"op\": \"=\", \"field\": \"x\", \"value\": \"y\"}], \"apiUrl\": \"api/grid.php\", \"busKey\": \"id\", \"fields\": [\"*\"], \"columns\": [{\"field\": \"id\", \"title\": \"#\", \"width\": 60, \"frozen\": true}, {\"field\": \"nome\", \"title\": \"Nome\", \"width\": 200}], \"orderBy\": [{\"dir\": \"desc\", \"field\": \"data\"}], \"pkField\": \"id\", \"pageSize\": 25, \"searchFields\": [\"Nome\", \"Città\"]}', 10, 1, '2026-09-28 21:49:53'),
(17, 'CSV', 'CSV Tabulator', 'base', 'Tabella che visualizza un file CSV locale o remoto (URL nel campo File del modello, mod_abs_url) — parsato interamente lato client, nessuna scrittura, nessun filtro, nessuna integrazione App Bus o flow FLE (l\'unico dei tre visualizzatori tabellari senza alcuna di queste tre cose).\n\nCampi: mod_spec è interamente OPZIONALE — se assente le colonne vengono auto-rilevate dal primo record del CSV.\n- view.columns (array, opzionale): stesso formato di DBJ, ogni voce { field, caption?, width?, mode? }.\n  - field: intestazione originale nella prima riga del CSV da mostrare in questa colonna.\n  - caption: etichetta mostrata al posto del nome originale (opzionale).\n  - width: larghezza colonna in pixel (opzionale).\n  - mode: \"r\" o \"rw\" (default \"rw\" se omesso) — ATTENZIONE: identica avvertenza del template DBJ qui sopra, \'rw\' rende la cella editabile solo visivamente, nessuna modifica viene mai salvata da nessuna parte, si perde al refresh.\n\nParsing supportato automaticamente: rilevamento delimitatore (\';\' vs \',\') dalle prime 5 righe, virgolette RFC 4180 (\"\" per virgolette letterali dentro un campo quotato), normalizzazione a capo (\\r\\n, \\r, \\n), prima riga = intestazioni.', '{\"view\": {\"columns\": [{\"mode\": \"r\", \"field\": \"nome\", \"width\": 200, \"caption\": \"Nome\"}, {\"mode\": \"rw\", \"field\": \"valore\", \"caption\": \"Valore\"}]}}', 10, 1, '2026-09-28 21:49:53'),
(18, 'ECH', 'Grafico — dati JSON inline', 'base', 'Grafico ECharts con dati incorporati direttamente nel mod_spec (nessuna chiamata di rete per i dati) — punto di partenza più semplice per capire lo schema completo, riusato dagli altri template ECH.\n\nCampi:\n- dataSource.type: sorgente dati — \"mysql\" (query SQL lato server), \"json\" (URL esterno o dati inline), \"csv_url\" (URL che produce CSV, es. export Google Sheets). Qui usiamo \"json\".\n- dataSource.inline: dati incorporati direttamente qui (array di oggetti) — alternativa a dataSource.url (fetch di un URL esterno che risponde JSON). Se sono presenti entrambi, inline ha priorità.\n- dataSource.url: (non usato in questo esempio) URL esterno da cui fare fetch() quando inline è assente.\n- dataSource.sql / dataSource.params: (solo per type=\"mysql\", non in questo esempio) query SQL e parametri — vedi template gemello \'Grafico — query MySQL\'.\n- dataSource.delimiter / dataSource.hasHeader: (solo per type=\"csv_url\") delimitatore CSV (default \",\") e se la prima riga è intestazione (default true).\n- dataSource.mapping: traduce i nomi di campo REALI dei tuoi dati nei nomi ASTRATTI che il template si aspetta (category/value/series per i grafici a barre/linee, x/y per lo scatter, source/target per sankey/grafo, ecc. — dipende dal template scelto, vedi elenco sotto). Es. { category: \"città\", value: \"fatturato\" } se i tuoi record hanno chiavi \"città\"/\"fatturato\" invece di \"category\"/\"value\".\n- template: id del template di visualizzazione. Valori ammessi e forma dati attesa (DOPO il mapping): bar-basic/line-basic {category,value,series?} · pie-basic {name,value} · scatter-basic {x,y,name?,series?,size?} · radar-basic {indicator,value,series?} · sankey-basic {source,target,value} · heatmap-basic {x,y,value} · graph-basic {source,target} o {nodes,links} · tree-basic/treemap-basic/sunburst-basic (lista adiacenza {id,parent_id,name,value} o JSON tree) · gauge-basic {name,value,min?,max?} · calendar-basic {date,value} (date in formato YYYY-MM-DD).\n- templateConfig.title / subtitle: testo sopra il grafico.\n- templateConfig.colors: array di colori hex per le serie, in ordine.\n- templateConfig.showLegend / showTooltip / showDataZoom: booleani, mostrano/nascondono legenda, tooltip al hover, e la barra di zoom sull\'asse (dove supportata dal template).\n- templateConfig.dark: tema scuro/chiaro (alternabile anche a runtime dal menu destro del pannello, ma NON salvato lì — solo dal pannello \'Layout grafico\' della toolbar viene persistito).\n- templateConfig.horizontal: barre orizzontali invece che verticali (bar-basic).\n- templateConfig.stack: impila le serie invece di affiancarle (bar-basic/line-basic con series multiple).\n- templateConfig.smooth: linee curve invece che spezzate (line-basic).\n- optionOverrides: escape hatch — oggetto fuso (deep-merge) direttamente sull\'ECharts option finale, DOPO che il template ha fatto il suo lavoro. Usalo per qualsiasi opzione nativa ECharts non esposta da templateConfig (es. { animation: false }, aggiungere un secondo yAxis, ecc.) — richiede di conoscere l\'option format nativo di ECharts.\n\nSe sia dataSource sia template sono assenti, il pannello mostra un placeholder informativo invece di un errore.', '{\"template\": \"bar-basic\", \"dataSource\": {\"type\": \"json\", \"inline\": [{\"value\": 10, \"category\": \"A\"}, {\"value\": 20, \"category\": \"B\"}, {\"value\": 15, \"category\": \"C\"}], \"mapping\": {\"value\": \"value\", \"category\": \"category\"}}, \"templateConfig\": {\"dark\": false, \"stack\": false, \"title\": \"Il mio grafico\", \"colors\": [\"#5470c6\", \"#91cc75\"], \"smooth\": false, \"subtitle\": \"\", \"horizontal\": false, \"showLegend\": true, \"showTooltip\": true, \"showDataZoom\": false}, \"optionOverrides\": {}}', 10, 1, '2026-09-28 21:49:53'),
(19, 'ECH', 'Grafico — query MySQL', 'base', 'Variante con dati letti da una query SQL lato server invece che incorporati nel mod_spec — utile per grafici che devono restare aggiornati con il database senza dover riscrivere il modello ogni volta.\n\nCampi specifici di questa sorgente:\n- dataSource.type: \"mysql\".\n- dataSource.sql: query SELECT eseguita lato server da api/ech_data.php. RICHIEDE un utente amministratore (user_type=\'X\') — con un altro ruolo la richiesta viene rifiutata dal backend. Il server verifica che la stringa inizi con SELECT e usa prepared statement, ma resta comunque privilegio da amministratore: non esporre questo template a ruoli non fidati.\n- dataSource.params: array di parametri posizionali per eventuali placeholder ? nella query (prepared statement) — [] se la query non ne ha.\n- dataSource.mapping: come nel template \'Grafico — dati JSON inline\' — traduce gli alias delle colonne SQL (qui già \"category\"/\"value\" grazie ad AS nella query, quindi il mapping è identità; se le tue colonne SQL si chiamano diversamente, mappale qui invece di riscrivere la query).\n\ntemplate / templateConfig / optionOverrides: identici in struttura al template \'Grafico — dati JSON inline\' qui sopra — vedi quella voce per la spiegazione di ogni campo e l\'elenco completo dei template disponibili con la forma dati attesa da ciascuno.', '{\"template\": \"bar-basic\", \"dataSource\": {\"sql\": \"SELECT città AS category, SUM(fatturato) AS value FROM vendite GROUP BY città\", \"type\": \"mysql\", \"params\": [], \"mapping\": {}}, \"templateConfig\": {\"dark\": false, \"stack\": false, \"title\": \"Il mio grafico\", \"colors\": [\"#5470c6\", \"#91cc75\"], \"smooth\": false, \"subtitle\": \"\", \"horizontal\": false, \"showLegend\": true, \"showTooltip\": true, \"showDataZoom\": false}, \"optionOverrides\": {}}', 20, 1, '2026-09-28 21:49:53'),
(20, 'GSH', 'Google Sheet', 'base', 'Tabella di sola lettura che mostra un foglio Google Sheets pubblico, recuperato via export CSV (nessuna chiave API richiesta) da un proxy PHP server-side.\n\nPREREQUISITO indispensabile: il foglio Google deve essere condiviso con \"Chiunque abbia il link può visualizzare\" — altrimenti il server riceve una pagina di login HTML al posto del CSV e restituisce errore 403 con messaggio esplicito.\n\nCampi:\n- spreadsheetId (stringa, OBBLIGATORIO): l\'ID del foglio, si legge dalla URL di Google Sheets (https://docs.google.com/spreadsheets/d/QUESTO_ID/edit). Deve rispettare il pattern [A-Za-z0-9_-]{20,80} (validazione anti-SSRF lato server) — copialo esatto dalla barra indirizzi, senza aggiungere altro.\n- gid (stringa, opzionale, default \"0\"): identifica quale scheda/tab del foglio leggere — si trova nella URL dopo \'#gid=\' quando sei su quella scheda. \"0\" = prima scheda.\n- apiUrl (stringa, opzionale, default \"api/gsh_data.php\"): endpoint proxy — cambialo solo se hai un endpoint dedicato compatibile.\n- hasHeaders (bool, opzionale, default true): se true la prima riga del foglio è trattata come intestazioni di colonna; se false le colonne si chiamano col_1, col_2, ...\n- limit (numero, opzionale, default 1000, tetto massimo 10000 imposto dal server): righe massime caricate per richiesta.\n- pageSize (numero, opzionale, default 25): righe per pagina nella griglia Tabulator.\n- autoRefresh (numero, secondi, opzionale, default 0): se >0, il pannello si auto-aggiorna a questo intervallo; 0 = nessun auto-refresh.\n- searchFields (array, opzionale, default: tutte le colonne): campi su cui agisce la ricerca full-text client-side (debounce 350ms) nella toolbar interna.\n- busKey (stringa, opzionale): campo usato per l\'evento App Bus \'selection:change\' al click riga (payload { objId, sourceApp:\'GSH\', field, value, row }) — se assente, click senza emissione bus (con avviso in status+console).\n- columns (array, opzionale, default: auto-rilevate dalla prima riga): definizione colonne, ogni voce { field, title?, width?, formatter? }. formatter condivisi con MYS (\"date\", \"datetime\", \"money\", \"boolean\", \"badge\" — quest\'ultimo richiede anche colors:{valore:\"#hex\",...}), più due esclusivi di GSH: \"link\" (rende il valore un <a target=\"_blank\">) e \"image\" (rende il valore un <img>, utile per URL di immagini in una cella).\n- sheetName (stringa, opzionale): etichetta mostrata nel menu sinistro quando l\'oggetto ha più schede/modelli collegati (multi-tabella) — se assente usa mod_name o \"Scheda N\".\n\nModulo di SOLA LETTURA: nessuna scrittura verso il foglio è possibile da questa interfaccia (richiederebbe OAuth2 + Google Sheets API v4, non implementato).', '{\"gid\": \"0\", \"limit\": 1000, \"apiUrl\": \"api/gsh_data.php\", \"busKey\": \"id\", \"columns\": [{\"field\": \"Nome\", \"title\": \"Nome teatro\", \"width\": 200}, {\"field\": \"Data\", \"title\": \"Data\", \"formatter\": \"date\"}], \"pageSize\": 25, \"hasHeaders\": true, \"autoRefresh\": 0, \"searchFields\": [\"Nome\", \"Città\"], \"spreadsheetId\": \"1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgVE2upms\"}', 10, 1, '2026-09-28 21:49:53'),
(21, 'HTM', 'HTML — Pagina esterna (iframe)', 'base', 'Mostra una pagina HTML COMPLETA (con i suoi stili e script) dentro un <iframe> isolato: adatto a siti esterni (Google Forms, YouTube /embed/, Google Maps \"incorpora\") o a pagine che non devono condividere nulla con la piattaforma. Gli script della pagina funzionano ma non raggiungono la sessione né le API.\n\nCampi:\n- mode: \"iframe\". Se mode manca e il modello ha un file o src, la modalità è comunque iframe.\n- src: indirizzo della pagina (alternativo al campo File del modello: se c\'è il file, src non serve).\n- srcdoc: HTML inline nell\'iframe, al posto di un indirizzo (riservato all\'amministratore).\n- sandbox: permessi dell\'iframe. Se omesso (consigliato) si sceglie da solo: stessa origine → con allow-same-origin, origine esterna → senza. allow-top-navigation è sempre escluso.\n- title: nome della pagina per i lettori di schermo; se omesso il nome del modello.\n\nMolti siti vietano di essere mostrati dentro altre pagine: il pannello resta bianco e non c\'è rimedio.\nPer pagine scritte da te che usano lo stile della piattaforma o aprono le sue finestre, usa invece \'HTML — Scheletro + Flow\'.', '{\"src\": \"https://docs.google.com/forms/d/e/XXXXX/viewform?embedded=true\", \"mode\": \"iframe\", \"title\": \"Questionario\"}', 10, 1, '2026-10-13 10:16:31'),
(22, 'HTM', 'HTML — Frammento inline (inject)', 'advanced', 'DISATTIVATO (2026-09-28): la modalità \"inject\" è stata rimossa. mode:\"inject\" ora si comporta come \"flow\": lo scheletro HTML viene inserito ripulito (niente <script>, attributi on*, link javascript:) e il codice va messo in un nodo HTM/Script di un flow collegato all\'oggetto.\n\nATTENZIONE — leggi prima di usare: questa modalità inietta il markup con innerHTML in un <div> SENZA alcun sandbox, e gli eventuali <script> contenuti vengono ri-attivati ed eseguiti nel PIENO CONTESTO della pagina (stessa origine, accesso completo al DOM, a Bootstrap e ai dati globali della piattaforma). Regola del progetto, ORA APPLICATA anche lato server: solo l\'amministratore (X) può salvare un mod_spec che risolve in questa modalità — un salvataggio da P/WPL viene rifiutato.\n\nA differenza di \'iframe\', il frammento condivide Bootstrap/ReseArch.css/i global della piattaforma con la pagina ospitante — adatto per frammenti (non pagine complete) che devono integrarsi visivamente col resto della dashboard.\n\nCampi:\n- mode: \"inject\" — forza questa modalità (vedi template gemello \'HTML — Pagina esterna\' per l\'auto-rilevamento quando il campo è omesso).\n- srcdoc: markup HTML inline iniettato direttamente nel div — qui puoi già usare classi Bootstrap (text-primary, lead, ecc.) perché il CSS è già caricato nella pagina ospitante.\n- src / mod_abs_url: (alternativa a srcdoc, non usata in questo esempio) URL di un file HTML: il modulo lo scarica con fetch(), estrae automaticamente il contenuto del tag <body> e inietta quello.\n- sandbox: NON ha alcun effetto in modalità inject (nessun iframe) — ignoralo qui.\n- title: usato come aria-label del div (accessibilità) — se omesso usa il nome del modello.\n\nSe ti serve interattività (bottoni, input, contenuto che cambia) SENZA eseguire script arbitrari, valuta il template gemello \'HTML — Scheletro + Flow (nodi DOM)\': più sicuro, e utilizzabile anche da PI/WPL.', '{\"mode\": \"inject\", \"srcdoc\": \"<h2 class=\'text-primary\'>Titolo</h2><p class=\'lead\'>Testo con Bootstrap già caricato.</p>\"}', 20, 0, '2026-10-03 16:39:53'),
(23, 'HTM', 'HTML — Scheletro + Flow (nodi DOM)', 'base', 'Pagina HTML scritta da te, inserita DENTRO la dashboard: usa Bootstrap, le icone e lo stile della piattaforma. Nessuno script viene eseguito: la logica, se serve, sta in un flow collegato all\'oggetto con i nodi \'HTM/DOM/*\' (DOM Query, On Event, Get/Set Value, Set Text, Set Class, Set Attr, Set Options, Chat View…).\n\nUso consigliato: scrivi la pagina in un file .html (oppure .txt, identico) e sceglilo come File del modello, con questa spec. I file .html si caricano solo se la cartella dei dati è protetta.\n\nCampi:\n- mode: \"flow\" — OBBLIGATORIO, non viene mai dedotto: senza, una pagina con file si apre in iframe (accenti sbagliati se manca la codifica, pulsanti della piattaforma senza effetto).\n- title: nome della pagina per i lettori di schermo.\n- srcdoc: in alternativa al file, HTML scritto nella spec. Riservato all\'amministratore (il salvataggio viene rifiutato agli altri).\n- src: indirizzo alternativo al file, stesso trattamento.\n\nDalla pagina vengono tolti <script>, <iframe>, <link>, <meta>, gli attributi on… e i link javascript:. Restano <style>, classi, icone, immagini, <details>.\nConsigli: stile confinato sotto una classe propria; uno sfondo sul contenitore (il pannello è trasparente); circa 36 px liberi in alto (l\'intestazione del pannello si sovrappone). I pulsanti con data-bs-toggle=\"modal\" data-bs-target=\"#modalModels\" (e #modalSubFolders, #modalUpload, #objectsEditModal, #modalObjModLinks, #modalFlows) aprono le finestre della piattaforma anche senza flow.\nEsempi completi: install/help/.', '{\"mode\": \"flow\", \"title\": \"Titolo della pagina\"}', 30, 1, '2026-10-13 10:16:31'),
(24, 'HTM', 'HTML — Scheda esercitazione HySpace (flow)', 'advanced', 'Pannello HTML che mostra la scheda dell\'esercitazione della stanza in cui ci si trova in un pannello HySpace aperto accanto (erede di WT3DNode_ViewEse.aspx): titolo, autore, descrizione, abstract, parole chiave e paragrafi con miniature ingrandibili, nello stile di Valenti_HySpace.css.\n\nNessuno scheletro HTML (srcdoc vuoto): la pagina la costruisce il nodo \'HTM/HYS/Scheda Esercitazione\', quindi questo modello è utilizzabile anche da PI/WPL.\n\nDopo aver creato il modello, collega all\'oggetto HTML un flow embedded con:\n1. \'ReseArch/App/Local Receiver\' — evento: hys:room:enter, bus: ON (riceve l\'ingresso in stanza pubblicato da HySpace);\n2. \'HTM/HYS/Scheda Esercitazione\' — collega trigger → trigger e payload → esercitazione.\nNel nodo della scheda puoi indicare un id_ese iniziale (mostrato all\'apertura, prima del primo ingresso in stanza) e scegliere se mostrare abstract e parole chiave.\n\nCampi:\n- mode: \"flow\" — obbligatorio.\n- title: aria-label del contenitore.', '{\"mode\": \"flow\", \"title\": \"Scheda esercitazione\"}', 40, 1, '2026-09-28 21:49:53'),
(25, 'HTM', 'HTML — Ricerca e musei HySpace (flow)', 'advanced', 'Pannello HTML di ricerca delle esercitazioni HySpace e di generazione di musei tematici (erede di WT3DNode_Search.aspx): cerca una o più parole (devono comparire tutte) in parole chiave, titolo, abstract, descrizione o cognome dello studente; \'Vai\' porta HySpace sull\'esercitazione; \'Genera museo\' crea un museo con i risultati (ogni esercitazione una stanza), con nome facoltativo (senza nome è temporaneo: 7 giorni) e salite/discese secondo il percorso dello studente o nessuna; \'I miei musei\' li riapre, rinomina, elimina.\n\nNessuno scheletro HTML: la pagina la costruisce il nodo \'HTM/HYS/Ricerca Musei\' (utilizzabile da PI/WPL). Richiede il database di HySpace (db_HySpace in cfg/cfg_MYSQL.php).\n\nFlow di QUESTO oggetto:\n- \'HTM/HYS/Ricerca Musei\': uscite vai + esercitazione → \'ReseArch/App/Local Emitter\' (evento hys:goto, bus ON); uscite apri museo + museo → un secondo \'Local Emitter\' (evento hys:museum, bus ON).\nFlow dell\'oggetto HySpace:\n- \'ReseArch/App/Local Receiver\' (hys:goto, bus ON) → \'HYS/Navigate/Go To\' (trigger→trigger, payload→esercitazione);\n- \'ReseArch/App/Local Receiver\' (hys:museum, bus ON) → \'HYS/Settings/Museum\' (trigger→trigger, payload→museo).\n\nCampi:\n- mode: \"flow\" — obbligatorio.\n- title: aria-label del contenitore.', '{\"mode\": \"flow\", \"title\": \"Ricerca e musei\"}', 50, 1, '2026-09-28 21:49:53'),
(26, 'HTM', 'HTML — Archivio esercitazioni HySpace (flow)', 'advanced', 'Pannello HTML con l\'archivio delle esercitazioni (erede di Ese_Archivio2.aspx / GestisciEsercitazioni.aspx): anno accademico, esercitazione, parole da cercare in titolo, parole chiave, abstract, descrizione o cognome, filtro \'solo con modello\'. Per ogni esercitazione: \'Scheda\' (testi formattati in un pannello Scheda), \'Vedi\' (modello in un pannello 3D TJS), clic sul titolo = entrambi. Solo per l\'amministratore: \'File\' (finestra per caricare e scaricare i file della cartella dell\'esercitazione) ed \'Elimina\' (esercitazione, paragrafi e cartella, con doppia conferma). Il modello si salva in GLB dal pannello 3D, così com\'è nella scena (con le modifiche), col nodo \'TJS/Model/Save Esercitazione\': un prompt propone il nome da confermare o rinominare; il GLB va nella cartella dell\'esercitazione e diventa il suo modello (campo modello_3d).\n\nNessuno scheletro HTML: la pagina la costruisce il nodo \'HTM/HYS/Archivio Esercitazioni\'. Richiede il database di HySpace (db_HySpace in cfg/cfg_MYSQL.php).\n\nDashboard con tre pannelli:\n1. QUESTO oggetto — flow: \'HTM/HYS/Archivio Esercitazioni\'; uscite scheda + esercitazione → \'ReseArch/App/Local Emitter\' (evento ese:scheda, bus ON); uscite vedi + modello → un secondo \'Local Emitter\' (evento ese:modello, bus ON).\n2. Oggetto HTML col template \'Scheda esercitazione HySpace (flow)\' — flow: \'Local Receiver\' (ese:scheda, bus ON) → \'HTM/HYS/Scheda Esercitazione\' (trigger→trigger, payload→esercitazione).\n3. Oggetto TJS (anche senza modelli collegati) — flow: \'Local Receiver\' (ese:modello, bus ON) → \'TJS/Model/Load URL\' (trigger→trigger, payload→url); uscita oggetto di Load URL → ingresso oggetto di \'TJS/Model/Save Esercitazione\'; \'ReseArch/Menu/Command\' (etichetta \'Salva modello\') → trigger di Save; uscite fatto + file di Save → \'Local Emitter\' (ese:salvato, bus ON).\nE nel flow di QUESTO oggetto anche: \'Local Receiver\' (ese:salvato, bus ON) → ingressi salvato + file dell\'Archivio (aggiorna la riga dopo il salvataggio).\n\nCampi:\n- mode: \"flow\" — obbligatorio.\n- title: aria-label del contenitore.', '{\"mode\": \"flow\", \"title\": \"Archivio esercitazioni\"}', 60, 1, '2026-09-28 21:49:53'),
(27, 'HYS', 'Stanza con pannelli espositivi', 'advanced', 'Configura le zone dove HySpace dispone automaticamente le immagini di un\'esercitazione, sulle pareti della stanza generata da QUESTO modello 3D, quando la stanza riceve un\'esercitazione. L\'assegnazione è automatica e segue il grafo HySpace (api/HySpace_rest_api.php): la stanza centrale espone l\'esercitazione corrente, le quattro laterali i vicini MFront/MLeft/MBack/MRight di WT3DNode, quelle sopra/sotto l\'esercitazione successiva/precedente dello stesso allievo. Una stanza senza esercitazione (vicino assente) resta vuota e la sua porta chiusa.\n\nQuesto NON è il mod_spec \"dell\'ambiente HYS\" nel suo complesso — è il mod_spec del singolo modello 3D (una delle 7 stanze del catalogo) che, oltre a essere un modello normale caricato da TJS-loaders.mjs, può opzionalmente descrivere dove appendere i pannelli. Il posizionamento globale della stanza nel sistema a 7 slot (C/L/R/F/B/U/D) è gestito internamente da HySpace stesso e NON dipende da mod_spec.transform (a differenza dei modelli TJS): se presente, un blocco \'transform\' qui verrebbe semplicemente ignorato.\n\nCampi (tutti dentro l\'oggetto \'expo\'):\n- expo.zones: array di ESATTAMENTE 8 elementi (una per ciascuna delle 8 zone-parete previste dall\'algoritmo di distribuzione immagini) — { x, z, rotDeg, width }.\n  - x, z: posizione orizzontale della zona nello spazio locale della stanza (stesse unità del modello 3D — tipicamente metri).\n  - rotDeg: rotazione della zona in gradi attorno all\'asse verticale — orienta il pannello per farlo aderire alla parete nel punto (x,z).\n  - width: larghezza disponibile della zona in metri — vincola quanto sono larghi/quanti affiancare i quadri generati in quella zona.\n  Una zona mancante (elemento null/assente in una posizione dell\'array) viene semplicemente saltata: se l\'esercitazione ha poche immagini, alcune zone possono restare vuote per design dell\'algoritmo di distribuzione, non serve compilarle tutte con contenuto reale.\n- expo.panelsY (numero, metri, opzionale, default 1.65): altezza da terra a cui sono centrati i pannelli.\n- expo.panelHeight (numero, metri, opzionale, default 3.0): altezza dei pannelli/quadri generati.\n- expo.panelMargin (numero, metri, opzionale, default 0.20): margine della cornice attorno a ogni immagine — il margine dell\'immagine vera e propria dentro la cornice è il doppio di questo valore.\n\nCampi opzionali dentro l\'oggetto \'hys\' (non inclusi nell\'esempio):\n- hys.start (true/false): questa è la forma della stanza di ingresso del museo. Senza flag vale la stanza chiamata \'Room_01\', altrimenti quella con mod_id più basso.\n- hys.door { width, height, distance } (metri, default 3, 3, 5): porta chiusa mostrata quando la stanza è la centrale e in una direzione non c\'è un vicino.\n\nI valori x/z/rotDeg di esempio qui sotto sono puramente illustrativi (un quadrato ideale di 8 pareti) — vanno adattati alla geometria REALE della tua stanza 3D (dove sono effettivamente le pareti nel file glTF/OBJ caricato).', '{\"expo\": {\"zones\": [{\"x\": 4.0, \"z\": 0.0, \"width\": 3.0, \"rotDeg\": 270}, {\"x\": 4.0, \"z\": 2.0, \"width\": 3.0, \"rotDeg\": 270}, {\"x\": 0.0, \"z\": 4.0, \"width\": 3.0, \"rotDeg\": 180}, {\"x\": -2.0, \"z\": 4.0, \"width\": 3.0, \"rotDeg\": 180}, {\"x\": -4.0, \"z\": 0.0, \"width\": 3.0, \"rotDeg\": 90}, {\"x\": -4.0, \"z\": -2.0, \"width\": 3.0, \"rotDeg\": 90}, {\"x\": 0.0, \"z\": -4.0, \"width\": 3.0, \"rotDeg\": 0}, {\"x\": 2.0, \"z\": -4.0, \"width\": 3.0, \"rotDeg\": 0}], \"panelsY\": 1.65, \"panelHeight\": 3.0, \"panelMargin\": 0.2}}', 10, 1, '2026-09-28 21:49:53'),
(28, 'TML', 'Timeline — Base', 'base', 'Timeline di eventi e periodi. I DATI stanno nel file del modello, un JSON:\n{ \"groups\": [ { \"id\": \"persone\", \"content\": \"Persone\", \"nested\": [\"artisti\"], \"open\": true } ],\n  \"items\":  [ { \"id\": \"e1\", \"start\": \"1452-04-15\", \"end\": \"1519-05-02\", \"content\": \"Leonardo\", \"group\": \"persone\", \"class\": [\"3\"], \"tags\": [\"arte\"], \"title\": \"nota\" } ] }\n(esempio completo: install/esempi/tml-esempio.json)\n\nDate: \"YYYY\", \"YYYY-MM\", \"YYYY-MM-DD\" o \"YYYY-MM-DDTHH:mm\"; anno negativo = avanti Cristo (-753 = 753 a.C.), l\'anno 0 non esiste. Un numero intero vale come anno.\nTipi di item: box (evento, default senza end), point, range (periodo, default con end), background (fascia di epoca dietro le corsie).\n\nQUESTO mod_spec dice solo come mostrarli:\n- view.start / view.end: finestra iniziale (assente = tutti gli item)\n- view.min / view.max: limiti di navigazione\n- view.zoomMin / view.zoomMax: durate come \"1d\", \"5000y\", \"30min\"\n- view.orientation: \"top\" o \"bottom\" (asse)\n- view.stack: impila gli item sovrapposti\n- view.era: \"auto\" (a.C. solo se serve), \"always\", \"never\"\n- view.cursor: data iniziale del cursore (linea verticale), null = nascosto\n- css: nomi di file .css nella STESSA CARTELLA del file del modello, applicati in ordine. Valgono solo in questo pannello. Classi utili: .tml-root (variabili --tml-*), .tml-c-<classe>, .tml-g-<gruppo>, .tml-tag-<tag>, .tml-t-range. Esempio: install/esempi/tml-esempio.css. Senza CSS ci sono le classi pronte \"1\"…\"12\".', '{\"css\": [], \"view\": {\"end\": null, \"era\": \"auto\", \"stack\": true, \"start\": null, \"cursor\": null, \"zoomMax\": \"5000y\", \"orientation\": \"top\"}}', 10, 1, '2026-10-07 08:53:26'),
(29, 'TML', 'Timeline — Foglio Google (eventi)', 'base', 'Un foglio (scheda) di Google Sheets con gli EVENTI della timeline. Il modello non ha file: questo mod_spec dice dove leggere.\n- spreadsheetId: dall\'URL del documento, docs.google.com/spreadsheets/d/<spreadsheetId>/edit\n- gid: dall\'URL della scheda aperta, …#gid=<gid> (0 = prima scheda)\n- role: \"items\"\n- layer: nome del livello (es. il documento: \"rossi\"); i fogli dello stesso documento hanno lo stesso layer\n- limit: righe massime (default 1000, massimo 10000)\n- mapping: facoltativo, se le colonne hanno altri nomi, es. {\"start\": \"Data\"}\n\nIl documento va condiviso con \"Chiunque abbia il link può visualizzare\".\n\nPrima riga = intestazioni: id (obbligatorio, stabile), tipo (punto, evento, periodo, epoca), inizio (obbligatorio), fine, etichetta, nota (tooltip), gruppo, classi e tag (più valori separati da |), obj_id (oggetto collegato). Le altre colonne finiscono in \"data\".\nDate: \"YYYY\", \"YYYY-MM\", \"YYYY-MM-DD\"; anno negativo = a.C. (-753). IMPORTANTE: colonne inizio e fine in Formato > Numero > Testo normale prima di scriverle, altrimenti Sheets le converte.\nNiente colori nel foglio: lo stile sta nei CSS del modello principale (classi .tml-c-<classe>, .tml-l-<livello>).', '{\"gid\": \"0\", \"role\": \"items\", \"layer\": \"\", \"limit\": 1000, \"spreadsheetId\": \"\"}', 20, 1, '2026-10-08 08:11:49'),
(30, 'TML', 'Timeline — Foglio Google (gruppi)', 'base', 'Un foglio di Google Sheets con i GRUPPI (corsie) della timeline.\n- spreadsheetId, gid: come per il foglio degli eventi\n- role: \"groups\"\n- layer: lo stesso degli eventi che usano queste corsie; vuoto = gruppi comuni a tutti i livelli\n\nPrima riga = intestazioni: id (obbligatorio), etichetta, padre (id del gruppo che lo contiene: corsie annidate), ordine (numero), aperto (sì/no), visibile (sì/no), classi (separate da |), nota.\nUn gruppo citato da un evento ma assente da questo foglio diventa una corsia semplice con l\'id come etichetta.', '{\"gid\": \"0\", \"role\": \"groups\", \"layer\": \"\", \"spreadsheetId\": \"\"}', 21, 1, '2026-10-08 08:11:49'),
(31, 'TML', 'Timeline — Foglio Google (epoche)', 'base', 'Un foglio di Google Sheets con le EPOCHE: fasce di sfondo dietro le corsie (es. \"Repubblica\", \"Impero\").\n- spreadsheetId, gid: come per il foglio degli eventi\n- role: \"eras\"\n- layer: lo stesso degli eventi del documento\n\nStesse colonne del foglio degli eventi (id, inizio, fine obbligatoria, etichetta, nota, classi); la colonna tipo è ignorata. Con la colonna gruppo la fascia vale solo per quella corsia, senza gruppo copre tutta la timeline.', '{\"gid\": \"0\", \"role\": \"eras\", \"layer\": \"\", \"spreadsheetId\": \"\"}', 22, 1, '2026-10-08 08:11:49'),
(32, 'TML', 'Timeline — Livelli', 'advanced', 'mod_spec PRINCIPALE (del file JSON del modello) per una timeline con più livelli: per esempio due documenti Google Sheets sulla stessa timeline, con lo stesso asse (zoom e cursore comuni).\nIl file JSON può essere anche vuoto: {} — serve come cartella dei CSS e per questo mod_spec.\n\n- view, css: come in \"Timeline — Base\"\n- layerMode: \"stack\" = livelli affiancati, uno sotto l\'altro, ognuno con le sue corsie; \"merge\" = fusi, le corsie con lo stesso id si uniscono (per confrontare cronologie). Si cambia anche dal menu destro.\n- layers: per ogni livello (il valore di \"layer\" nei fogli) label = etichetta, css = file .css nella cartella del modello accesi solo con il livello, visible = visibile all\'avvio.\n\nCon più livelli gli id degli eventi diventano \"<livello>:<id>\" (es. rossi:cesare) nei nodi e sul bus. Nel CSS: .tml-l-<livello> colpisce item e corsie di un livello, .tml-layer il gruppo radice.\nUn livello si accende e spegne dal menu sinistro o con il nodo TML/Layer/SetVisible.', '{\"css\": [], \"view\": {\"end\": null, \"era\": \"auto\", \"stack\": true, \"start\": null, \"cursor\": null, \"zoomMax\": \"5000y\", \"orientation\": \"top\"}, \"layers\": {\"rossi\": {\"css\": [], \"label\": \"Archivio Rossi\", \"visible\": true}, \"bianchi\": {\"css\": [], \"label\": \"Archivio Bianchi\", \"visible\": true}}, \"layerMode\": \"stack\"}', 23, 1, '2026-10-08 08:11:49'),
(33, 'OSD', 'Immagine gigapixel (Zoomify)', 'base', 'OpenSeadragon NON legge il mod_spec: lascia {}.\n\nIl File del modello è l\'ImageProperties.xml di un\'immagine tagliata in tasselli Zoomify (cartella con ImageProperties.xml e TileGroup0, TileGroup1…), per esempio con libvips: vips dzsave immagine.tif Nome --layout zoomify. Carica l\'INTERA cartella trascinandola nei Caricamenti (i file .xml si caricano solo se la cartella dei dati è protetta).\n\nUn\'immagine per oggetto: con più modelli collegati si usa solo il primo. Un modello senza file non va bene: serve sempre l\'immagine.\n\nDisegni e filtri immagine NON stanno nella spec: si salvano come disegni legati al modello (barra del pannello: File → Lista disegni). Per disegnare bisogna prima aprire o creare un disegno.', '{}', 10, 1, '2026-10-13 10:16:31');
INSERT INTO `mod_spec_templates` (`tpl_id`, `app_cod`, `tpl_name`, `tpl_level`, `tpl_help`, `tpl_spec`, `tpl_sort`, `is_active`, `updated_at`) VALUES
(34, 'VID', 'Video', 'base', 'Il visualizzatore video NON legge il mod_spec: lascia {}.\n\nUn modello per video (consigliato MP4 H.264 + AAC, al massimo 256 MB). Tutti i video collegati all\'oggetto formano una sequenza: alla fine di uno parte il successivo, dopo l\'ultimo si ricomincia; un video solo si ripete. Nome e descrizione del modello compaiono come suggerimento sul pallino del video nella barra del pannello.\n\nIl video parte senza audio (regola dei browser): l\'audio si attiva dai comandi del video.', '{}', 10, 1, '2026-10-13 10:16:31'),
(35, 'IFC', 'Modello BIM (Fragments)', 'base', 'Il visualizzatore BIM NON legge il mod_spec: lascia {}.\n\nIl File del modello deve essere un .frag (That Open Fragments), convertito dall\'.ifc con @thatopen/components. L\'apertura diretta di un .ifc oggi NON funziona (errore \"Unsupported input type\"). Più modelli collegati (architettonico, strutture, impianti) si caricano insieme.\n\nModulo parziale: barra degli strumenti, proprietà degli elementi e sezioni non sono ancora disponibili. Per un edificio da esplorare con sezioni, misure e luci, esportalo in glTF/GLB e usa l\'App 3D (TJS).', '{}', 10, 1, '2026-10-13 10:16:31'),
(36, 'OLY', 'Cartografia — Base', 'base', 'Mappa con fondo OpenStreetMap. Vale la spec del PRIMO modello dell\'oggetto.\n- view.center: [longitudine, latitudine] in gradi (WGS84), es. [12.4924, 41.8902] = Colosseo\n- view.zoom: da 0 (mondo) a 22 (dettaglio); 16-18 = quartiere/edificio\n- view.rotation: rotazione della mappa in gradi\n- crs: sistema delle coordinate mostrate nel footer: \"EPSG:4326\" (lat/lon), \"EPSG:3857\", \"EPSG:3003\"/\"EPSG:3004\" (Gauss-Boaga), \"EPSG:6707\"/\"EPSG:6708\" (RDN2008 UTM), \"EPSG:25832\"/\"EPSG:25833\", \"EPSG:32632\"/\"EPSG:32633\". Si cambia anche dal menu della barra.\n- base: fondo, id del catalogo lib/map-services.json (\"osm\", \"opentopomap\", \"esri-imagery\") o \"none\".\r\nOgni modello è anche un layer, se è un file GeoJSON/KML/GPX/GeoTIFF, un\'immagine con extent o un servizio (template \"Cartografia — Layer …\").', '{\"crs\": \"EPSG:4326\", \"base\": \"osm\", \"view\": {\"zoom\": 16, \"center\": [12.4924, 41.8902], \"rotation\": 0}}', 10, 1, '2026-11-04 21:22:29'),
(37, 'OLY', 'Cartografia — Layer vettoriale', 'base', 'Modello con un file GeoJSON (.geojson/.json), KML o GPX: un layer di punti, linee, poligoni.\r\n- title: nome nella finestra Layer (vuoto = nome del modello)\r\n- visible: false = spento all\'apertura; opacity: da 0 a 1\r\n- style: stroke (colore del bordo), width, fill (colore di riempimento, anche rgba), radius e pointColor (punti), label (nome dell\'attributo da scrivere sulla mappa), labelColor. Per KML senza style restano gli stili del file.\r\n- dataProjection: sistema delle coordinate del GeoJSON, se non è WGS84 e il file non lo dichiara (es. \"EPSG:3004\")', '{\"style\": {\"fill\": \"rgba(225, 29, 72, 0.18)\", \"label\": null, \"width\": 2, \"radius\": 5, \"stroke\": \"#e11d48\"}, \"title\": \"\", \"opacity\": 1, \"visible\": true}', 20, 1, '2026-11-04 21:22:29'),
(38, 'OLY', 'Cartografia — Layer immagine georiferita', 'base', 'Modello con un\'immagine (.jpg, .png, .webp), per esempio una mappa storica, messa sulla mappa con i suoi estremi.\r\n- extent: [minX, minY, maxX, maxY] nel sistema projection (in WGS84: [lon ovest, lat sud, lon est, lat nord])\r\n- projection: \"EPSG:4326\" (default), \"EPSG:3004\", \"EPSG:6708\"…\r\n- title, visible, opacity come gli altri layer (opacity 0.6-0.8 per vedere il fondo).\r\nUn\'immagine senza extent non è un layer.', '{\"title\": \"\", \"extent\": [12.49, 41.889, 12.495, 41.892], \"opacity\": 0.7, \"projection\": \"EPSG:4326\"}', 30, 1, '2026-11-04 21:22:29'),
(39, 'OLY', 'Cartografia — Layer GeoTIFF', 'base', 'Modello con un file GeoTIFF (.tif/.tiff), meglio se COG (Cloud Optimized GeoTIFF). Se il file è in EPSG:3857 si legge a pezzi (adatto ai file grandi); negli altri sistemi si legge l\'immagine intera ridotta a 4096 px di lato e la si riproietta: per raster grandi conviene convertirli prima in EPSG:3857 COG (es. gdalwarp -t_srs EPSG:3857 -of COG).\r\n- projection: solo se il file non dichiara il suo sistema\r\n- title, visible, opacity come gli altri layer.', '{\"title\": \"\", \"opacity\": 1}', 40, 1, '2026-11-04 21:22:29'),
(40, 'OLY', 'Cartografia — Layer da servizio', 'base', 'Modello senza file (\"Nessun file\") che mostra un servizio del catalogo lib/map-services.json, curato dall\'amministratore.\r\n- service: id del servizio, es. \"catasto-ade\" (particelle e fabbricati, visibile solo a scala di dettaglio)\r\n- title, visible, opacity come gli altri layer.\r\nPer aggiungere servizi al catalogo serve l\'amministratore.', '{\"opacity\": 0.8, \"service\": \"catasto-ade\"}', 50, 1, '2026-11-04 21:22:29');
